{"result":"{
  "metadata": {
    "id": "268337165",
    "title": "7.1b Third Party Credentials",
    "type": "page",
    "created": "",
    "updated": "",
    "url": "https://zimmermannworkboard.atlassian.net/wiki/spaces/SFCC/pages/268337165",
    "space": {
      "key": "SFCC",
      "name": "Adobe SFCC"
    },
    "version": 4,
    "attachments": [],
