content.content:
./.mcp.json
---settings---
{
  "hooks": {
    "PreToolUse": [
      {
        "matcher": "Write|Edit|NotebookEdit",
        "hooks": [
          {
            "type": "command",
            "command": "branch=$(git branch --show-current 2>/dev/null); if [ \"$branch\" = 'develop' ] || [ \"$branch\" = 'main' ]; then echo \"BLOCKED: You are on branch '$branch'. Claude Code must not make file changes on develop or main. Switch to a feature branch first.\"; exit 1; fi"
          },
          {
            "type": "command",
            "command": "[ -f .claude/hooks/tier2Warn.sh ] && bash .claude/hooks/tier2Warn.sh || true"
          }
        ]
      }
    ],
    "PostToolUse": [
      {
        "matcher": "Write",
        "hooks": [
          {
            "type": "command",
            "command": "root=$(git rev-parse --show-toplevel 2>/dev/null) && f=$(jq -r '.tool_input.file_path') && \"$root/node_modules/.bin/prettier\" --write \"$f\" 2>&1 || true",
            "statusMessage": "Formatting new file with Prettier..."
          }
        ]
      },
      {
        "matcher": "Edit|Write",
        "hooks": [
          {
            "type": "command",
            "command": "[ -f .claude/hooks/contentfulDriftWarn.sh ] && bash .claude/hooks/contentfulDriftWarn.sh || true"
          },
          {
            "type": "command",
            "command": "[ -f .claude/hooks/registryUpdate.sh ] && bash .claude/hooks/registryUpdate.sh || true"
          }
        ]
      },
      {
        "matcher": "Write",
        "hooks": [
          {
            "type": "command",
            "command": "[ -f .claude/hooks/testFileRemind.sh ] && bash .claude/hooks/testFileRemind.sh || true"
          }
        ]
      }
    ],
    "Stop": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "[ -f .claude/hooks/session-reflect.sh ] && bash .claude/hooks/session-reflect.sh || true"
          }
        ]
      }
    ]
  },
  "permissions": {
    "allow": [
      "Bash(git branch*)",
      "Bash(git status*)",
      "Bash(git diff*)",
      "Bash(git log*)",
      "Bash(git show*)",
      "Bash(find . *)",
      "Bash(grep *)",
      "Bash(ls *)",
      "Bash(npm run lint*)",
      "Bash(npm run test*)",
      "Bash(npm run build*)",
      "Bash(gh pr *)",
      "Bash(gh api *)",
      "Bash(gh issue *)"
    ]
  }
}
---mcp file---
{
  "mcpServers": {
    "mcp-atlassian": {
      "command": "uvx",
      "args": ["mcp-atlassian"],
      "env": {
        "JIRA_URL": "${JIRA_URL}",
        "JIRA_USERNAME": "${JIRA_USERNAME}",
        "JIRA_API_TOKEN": "${JIRA_API_TOKEN}",
        "CONFLUENCE_URL": "${CONFLUENCE_URL}",
        "CONFLUENCE_USERNAME": "${CONFLUENCE_USERNAME}",
        "CONFLUENCE_API_TOKEN": "${CONFLUENCE_API_TOKEN}"
      }
    }
  }
}
---env sample grep---
#                    (your own Atlassian token, your own Contentful CMA token)
#                    that must never be centralized — still lives in
#                    .env.shared, but `push`/`init`'s pull skip it entirely.
#                    Each developer fills this in themselves.
--
# ── Atlassian MCP (mcp-atlassian, .mcp.json) — Jira/Confluence ────────────────
# USERNAME/API_TOKEN are a PERSONAL API token per developer — different
# consultants/engagements may use different Atlassian accounts, so these are
# never committed with real values and never pushed to GitHub Environments
# (each developer generates their own — pushing one person's token would put
# everyone else's actions in Jira/Confluence under that person's identity).
# URL is the shared org instance, same for everyone, safe to centralize.
# Requires `uv`/`uvx` installed (https://docs.astral.sh/uv/). Claude Code does
# NOT read .env automatically — export these into your shell before running
--
# Generate a token at: https://id.atlassian.com/manage-profile/security/api-tokens
# scope:shared
JIRA_URL=
# scope:personal
JIRA_USERNAME=
# scope:personal
JIRA_API_TOKEN=
# scope:shared
CONFLUENCE_URL=
# scope:personal
CONFLUENCE_USERNAME=
# scope:personal
CONFLUENCE_API_TOKEN=

# ── BrowserStack Automate — local story testing (npm run test:story) ─────────
# Same vars qa.yml's e2e-browserstack job uses as CI secrets, now needed

